CREATE PROCEDURE GetEmployeesByDept
    @DeptName VARCHAR(50)
AS
BEGIN
    SELECT employee_id, name, salary
    FROM Employees
    WHERE Department = @DeptName;
END;

-- EXEC GetEmployeesByDept @DeptName = 'Engineering';

