16.syntax:
SELECT employee_id, name, salary
FROM Employees
WHERE salary > (SELECT AVG(salary) FROM Employees);

21.syntax:
SELECT employee_id, department, salary,
       AVG(salary) OVER (PARTITION BY department) AS dept_avg_salary
FROM Employees;

