36.syntax:
CREATE PROCEDURE GetCustomersByCountryCity
    @Country VARCHAR(50),
    @City VARCHAR(50)
AS
BEGIN
    SELECT customer_id, customer_name, city, country
    FROM Customer
    WHERE country = @Country AND city = @City;
END;

EXEC GetCustomersByCountryCity @Country = 'USA', @City = 'New York';

